import type { Pregunta } from '../quiz';

// Nivel MEDIA (español) · 142 preguntas: distinguir conceptos y reconocerlos en situaciones concretas.
// Convención: la PRIMERA opción es siempre la correcta (en pantalla se mezclan al azar).

export const media: Pregunta[] = [
  // ── El modelo ecológico ──
  { p: 'Antecedentes de conductas agresivas, adicciones o fracaso escolar son factores de riesgo del nivel…', o: ['Individual', 'Relacional', 'Mesosocial', 'Macrosocial'], e: 'El plano individual reúne factores de la historia personal: edad, educación, empleo, antecedentes.', t: 'modelo-ecologico' },
  { p: 'Hacinamiento, desempleo y falta de espacios recreativos en un barrio son factores del nivel…', o: ['Mesosocial', 'Individual', 'Relacional', 'Histórico'], e: 'Son factores de riesgo del nivel mesosocial (barrio, escuela, trabajo), no causas: según Belém do Pará, la violencia contra la mujer atraviesa clases, ingresos y culturas.', t: 'modelo-ecologico' },
  { p: 'Haber presenciado violencia en la familia de origen es un factor de riesgo del nivel…', o: ['Relacional', 'Macrosocial', 'Histórico', 'Mesosocial'], e: 'Vivir en ambientes familiares violentos puede predisponer, no determinar, a sufrir o ejercer violencia más adelante. Es un factor de riesgo del plano relacional (Heise, 1998).', t: 'modelo-ecologico' },
  { p: '¿Por qué el modelo ecológico pide intervenir con varios sectores de política pública a la vez?', o: ['Porque la violencia de género es polifacética', 'Porque cada sector tiene poco presupuesto', 'Porque así lo exige la Constitución Nacional', 'Porque la violencia depende solo de la justicia'], e: 'La violencia de género es compleja y polifacética, con raíces biográficas, psicológicas, sociales y ambientales: no tiene una solución sencilla ni única.', t: 'modelo-ecologico' },
  { p: 'En el ámbito educativo, ¿a qué pregunta permite pasar el modelo ecológico, más allá de las causas del acoso escolar?', o: ['¿Qué sentido le dan los actores?', '¿Qué sanción corresponde aplicar?', '¿Cuál es el historial del alumno?', '¿Qué dicen las estadísticas?'], e: 'Permite preguntarse por el sentido que los propios actores le dan al acoso.', t: 'modelo-ecologico' },
  { p: 'En políticas públicas, la palabra “modelo” alude a…', o: ['Los componentes que debe integrar una ley o política', 'Un caso ejemplar que otros países copian tal cual lo hicieron', 'Un formulario oficial para realizar denuncias', 'Un programa electoral de un partido político'], e: 'Elementos teóricos y técnicos que definen el problema y organizan acciones y recursos.', t: 'modelo-ecologico' },

  // ── Violencia de género ──
  { p: 'Una funcionaria demora sin motivo el acceso de una mujer a un programa estatal. ¿Qué modalidad de violencia es?', o: ['Institucional', 'Doméstica', 'Mediática', 'Pública-política'], e: 'La institucional la ejercen agentes de instituciones públicas que retardan u obstaculizan el acceso a derechos.', t: 'violencia-de-genero' },
  { p: 'Pedir un test de embarazo como requisito para un empleo es violencia…', o: ['Laboral', 'Obstétrica', 'Institucional', 'Contra la libertad reproductiva'], e: 'La laboral discrimina en el acceso al empleo: estado civil, maternidad, edad, test de embarazo.', t: 'violencia-de-genero' },
  { p: 'Una publicidad que muestra a las mujeres como objetos, ¿en qué modalidad de violencia encuadra?', o: ['Mediática', 'Obstétrica', 'Laboral', 'Doméstica'], e: 'Por su modalidad (Ley 26.485, art. 6) es mediática: difunde imágenes estereotipadas que humillan o legitiman la desigualdad. Por su tipo (art. 5) es, además, violencia simbólica.', t: 'violencia-de-genero' },
  { p: 'Impedirle a una mujer decidir cuántos embarazos tener y cada cuánto, ¿qué modalidad de violencia es según el art. 6?', o: ['Contra la libertad reproductiva', 'Obstétrica, en la atención del parto', 'Mediática, por imágenes estereotipadas', 'En el espacio público'], e: 'Vulnera el derecho a decidir el número de embarazos y el intervalo entre nacimientos (Ley 26.485, art. 6; Ley 25.673). La obstétrica, en cambio, refiere al trato deshumanizado en la atención (Ley 25.929).', t: 'violencia-de-genero' },
  { p: 'Hostigar y amenazar a una candidata para que abandone la campaña es violencia…', o: ['Pública-política', 'Mediática', 'Laboral', 'En el espacio público'], e: 'Es la modalidad pública-política (Ley 26.485, art. 6): intimidación, hostigamiento, descrédito o amenazas que impiden o limitan la vida política.', t: 'violencia-de-genero' },
  { p: '¿Qué alcance tiene la definición de violencia contra las mujeres de la Ley 26.485?', o: ['Incluye la que ejercen agentes del Estado', 'Abarca solo el ámbito privado y familiar', 'Deja afuera lo que ocurre en el espacio digital', 'Exige que la víctima conviva con el agresor'], e: 'El art. 4 incluye las violencias perpetradas desde el Estado o por sus agentes, en el ámbito público y en el privado; desde la Ley 27.736 abarca el espacio digital, y la modalidad doméstica no requiere convivencia.', t: 'violencia-de-genero' },
  { p: 'En el iceberg de la violencia, “humillar, desvalorizar e ignorar” son…', o: ['Formas explícitas que no se ven', 'Formas visibles, en la punta', 'Formas sutiles, en la base', 'Formas que quedan fuera del iceberg'], e: 'En el iceberg de Amnistía Internacional son formas explícitas que no se ven: están bajo la superficie, pero por encima de la base, donde quedan las sutiles (humor y lenguaje sexistas, micromachismos).', t: 'violencia-de-genero' },

  // ── Ciclo de la violencia ──
  { p: 'Una pareja vive semanas de roces y la sensación de que algo va a estallar. ¿En qué fase está?', o: ['Acumulación de tensión', 'Luna de miel', 'Período violento', 'Temor a perder la relación'], e: 'Crecen los roces y la sensación de que en cualquier momento habrá una discusión explosiva.', t: 'ciclo-de-la-violencia' },
  { p: 'Después de una agresión llegan regalos y la promesa de que “no va a volver a pasar”. ¿Qué fase es?', o: ['Temor a perder la relación', 'Acumulación de tensión', 'Fin definitivo del ciclo violento', 'Período violento'], e: 'Arrepentimiento y promesas de cambio; después se vuelve a la luna de miel.', t: 'ciclo-de-la-violencia' },
  { p: 'Según el ciclo de Walker, ¿qué hace tan difícil salir de una relación violenta?', o: ['Que haya etapas de calma y promesas de cambio', 'Que la violencia es constante y sin pausas', 'Que la ley no contempla la violencia en la pareja', 'Que la violencia ocurre una sola vez'], e: 'La calma y las promesas alimentan la esperanza de que todo cambie, pero son parte del mismo ciclo, no el fin de la violencia. Conocerlo permite acompañar sin juzgar (Walker, 1979).', t: 'ciclo-de-la-violencia' },
  { p: 'Según Lenore Walker, en muchas parejas violentas la violencia…', o: ['Sigue un ciclo que se repite', 'Termina con la luna de miel', 'Aparece recién al separarse', 'Se detiene con las promesas'], e: 'Walker (1979) describió que la violencia no es constante: sigue un ciclo que se repite. La calma y las promesas forman parte del mismo ciclo; no significan que la violencia terminó.', t: 'ciclo-de-la-violencia' },
  { p: 'Tras semanas de roces, él la insulta, la amenaza y le rompe el celular, pero no la golpea. ¿En qué fase del ciclo están?', o: ['Período violento', 'Acumulación de tensión', 'Temor a perder la relación', 'Luna de miel'], e: 'En el período violento estalla la violencia en cualquiera de sus formas: física, psicológica (amenazas, insultos), sexual, económica (romper bienes) o simbólica. No hacen falta golpes.', t: 'ciclo-de-la-violencia' },

  // ── Efectos de la violencia de género en las infancias ──
  { p: 'Una niña de 8 años cuida a sus hermanos y consuela a su madre después de cada episodio violento. ¿Qué señal muestra?', o: ['Parentalización', 'Normalización', 'Conducta regresiva', 'Aislamiento social'], e: 'Asume roles de cuidado y protección que no corresponden a su edad.', t: 'efectos-en-las-infancias' },
  { p: 'Un niño vive violencia en su casa pero no muestra ninguna señal visible. ¿Qué se puede concluir?', o: ['Que igual puede estar afectado', 'Que la violencia no lo afectó', 'Que ya la superó por su cuenta', 'Que no hace falta incluirlo en la ayuda'], e: 'Ninguna señal prueba por sí sola que haya violencia, y que no aparezcan no la descarta: muchas niñas y niños no lo expresan de ningún modo.', t: 'efectos-en-las-infancias' },
  { p: 'Un adolescente dice que en su casa "se grita y se pega como en todas las casas". ¿Qué señal muestra?', o: ['Normalización', 'Parentalización', 'Conducta regresiva', 'Estrés postraumático'], e: 'Ver la violencia como una forma "normal" de relacionarse, o quitarle importancia, es normalizarla.', t: 'efectos-en-las-infancias' },
  { p: 'Al intervenir con una mujer en situación de violencia, ¿qué recomienda la guía sobre sus hijos?', o: ['Incluirlos, con espacios propios para ellos', 'Esperar a que la madre se recupere primero', 'Separarlos de la madre mientras dure la ayuda', 'No involucrarlos, para no exponerlos más'], e: 'Hay que incluir también a hijas e hijos, con espacios específicos, y que la madre participe del acompañamiento.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué es la victimización secundaria?', o: ['El daño que causa una intervención inadecuada', 'La violencia que sufre un hermano menor', 'Una segunda agresión del mismo agresor', 'El miedo a que la violencia se repita'], e: 'Son las intervenciones fragmentadas o inadecuadas que vuelven a dañar a quien ya fue víctima.', t: 'efectos-en-las-infancias' },
  { p: 'Sobre el contacto con el padre denunciado, ¿qué postura predomina en las sentencias?', o: ['Decidir según la gravedad de cada caso', 'Suspenderlo siempre, de forma automática', 'Mantenerlo aunque haya riesgo', 'Dejar que lo decidan los propios hijos'], e: 'La postura que predomina se guía por el interés superior del niño y decide según la gravedad. Otra postura, de profesionales y juristas, pide suspenderlo siempre cuando hay violencia de género.', t: 'efectos-en-las-infancias' },

  // ── Igualdad y no discriminación ──
  { p: '¿Qué implica para los Estados el principio de igualdad y no discriminación?', o: ['Una obligación reforzada con grupos en situación de vulnerabilidad', 'Un trato idéntico para todas las personas, sin hacer ninguna distinción', 'Una recomendación sin obligaciones concretas para el Estado', 'Un deber que tienen solamente los jueces y tribunales'], e: 'Capítulo 4 del Compendio de la CIDH: implica una obligación reforzada de proteger a los grupos en situación de vulnerabilidad.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué deben garantizar especialmente los Estados a las mujeres en situación de pobreza?', o: ['Salud, trabajo y derechos económicos', 'El voto y la participación política', 'El cupo laboral travesti trans', 'Los derechos digitales en redes'], e: 'Atención especial a sus derechos económicos y al ejercicio efectivo de la salud y el trabajo.', t: 'igualdad-y-no-discriminacion' },
  { p: 'Según la CEDAW, la discriminación contra la mujer es toda distinción basada en el sexo que…', o: ['Menoscabe o anule el goce de sus derechos', 'Se haga en público y con intención de dañar', 'Figure en un documento oficial', 'Ocurra dentro del ámbito laboral'], e: 'Por objeto o por resultado, en cualquier esfera: no hace falta intención.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué tipo de política exige la CEDAW a los Estados para eliminar la discriminación?', o: ['Inmediata, comprehensiva y multisectorial', 'Progresiva, comprehensiva y multisectorial', 'Inmediata, parcial y multisectorial', 'Inmediata, comprehensiva y por sectores'], e: 'La CEDAW exige una política inmediata (no gradual), comprehensiva (no parcial) y multisectorial (no organizada sector por sector).', t: 'igualdad-y-no-discriminacion' },
  { p: '¿En qué instrumentos se apoyan los estándares interamericanos sobre las mujeres?', o: ['DADDH, CADH y Belém do Pará', 'CEDAW, OMS y Ley 26.485', 'Leyes 26.618, 26.743 y 26.791', 'Declaración de Bogotá y OPS'], e: 'Declaración Americana, Convención Americana y Convención de Belém do Pará.', t: 'igualdad-y-no-discriminacion' },

  // ── Legislación ──
  { p: '¿Qué ley argentina aprobó la Convención de Belém do Pará?', o: ['La Ley 24.632', 'La Ley 26.485', 'La Ley 26.061', 'La Ley 27.736'], e: 'La Ley 24.632 (1996) aprobó la Convención de Belém do Pará.', t: 'legislacion' },
  { p: '¿Qué incorporó la Ley 27.736 (2023) a la Ley 26.485?', o: ['El espacio digital', 'La violencia obstétrica', 'El cupo laboral travesti trans', 'El matrimonio igualitario'], e: 'Sumó los derechos y bienes digitales de las mujeres y la violencia en el espacio digital.', t: 'legislacion' },
  { p: 'El art. 3 de la Ley 26.485 protege el derecho a un trato respetuoso que evite…', o: ['La revictimización', 'La publicidad', 'La reconciliación', 'La investigación'], e: 'Evitar toda conducta, acto u omisión que produzca revictimización.', t: 'legislacion' },
  { p: 'Según el art. 7 de la Ley 26.485, ¿cómo debe ser la asistencia a las mujeres que padecen violencia?', o: ['Gratuita, rápida, transparente y eficaz', 'Arancelada, pero rápida y eficaz', 'Gratuita, pero solo cuando existe una denuncia', 'Voluntaria y a cargo de las ONG'], e: 'Asistencia integral y oportuna, con acceso gratuito, rápido, transparente y eficaz.', t: 'legislacion' },
  { p: '¿Qué prohíbe el art. 7 de la Ley 26.485 sobre la información de situaciones de violencia?', o: ['Difundirla sin autorización de quien la padece', 'Guardarla en registros oficiales del Estado nacional', 'Usarla para estadísticas anónimas', 'Compartirla con la justicia cuando lo pide'], e: 'Protege la confidencialidad y la intimidad de quien padece la violencia.', t: 'legislacion' },
  { p: 'Según el art. 9 de la Ley 26.485, ¿qué modelos de abordaje NO se admiten?', o: ['Los que incluyan mediación o negociación', 'Los que empoderen a las mujeres', 'Los que sean integrales, gratuitos y accesibles', 'Los que trabajen con universidades'], e: 'Se garantizan modelos que empoderen a las mujeres, sin admitir mediación ni negociación.', t: 'legislacion' },
  { p: '¿Qué contempla el inciso 11 del art. 80 del Código Penal?', o: ['Matar a una mujer mediando violencia de género', 'Matar por odio de género o a la orientación sexual', 'Matar a la pareja o expareja, conviva o no', 'Matar para hacer sufrir a una expareja'], e: 'El inciso 11 es el femicidio: matar a una mujer cuando lo hace un hombre y media violencia de género, con prisión perpetua. Las otras opciones son los incisos 4, 1 y 12.', t: 'legislacion' },

  // ── Micromachismos ──
  { p: 'Usar el silencio para no dar explicaciones e imponer el no diálogo es un micromachismo…', o: ['Encubierto', 'Utilitario', 'De crisis', 'Coercitivo'], e: 'Es una forma de “creación de falta de intimidad”, dentro de los encubiertos.', t: 'micromachismos' },
  { p: 'Cuando la mujer gana poder, aparecen maniobras para volver a la desigualdad anterior. ¿Qué categoría es?', o: ['De crisis', 'Utilitarios', 'Encubiertos', 'Coercitivos'], e: 'Los de crisis fuerzan la permanencia en el statu quo desigual cuando se desequilibra.', t: 'micromachismos' },
  { p: 'Retener poder mediante la fuerza psicológica o moral es un micromachismo…', o: ['Coercitivo', 'Encubierto', 'Utilitario', 'De crisis'], e: 'Los coercitivos usan la fuerza psicológica o moral masculina.', t: 'micromachismos' },
  { p: 'Responderle a una mujer “exagerás” o “estás loca” cuando reclama es…', o: ['Inocentización culpabilizadora', 'Seudonegociación', 'Creación de falta de intimidad', 'Autoindulgencia'], e: 'El varón se ubica como juez y nunca como responsable.', t: 'micromachismos' },
  { p: '¿Qué es el poder autoafirmativo?', o: ['La capacidad de decidir y existir con autonomía', 'El control sobre la vida y las decisiones de otras personas', 'El poder legitimado solo para las mujeres', 'La fuerza física para imponerse a otros'], e: 'Es la capacidad de hacer y transformar. El de dominio, en cambio, controla la vida de otros.', t: 'micromachismos' },
  { p: 'Según Bonino, cuando un varón no reconoce los aportes de su pareja (“ninguneo”), en ella aparece…', o: ['Hambre de afecto: valora de más lo poco', 'Indiferencia ante lo poco que él aporta', 'Más seguridad y autonomía en ella misma', 'Un reparto más justo de las tareas'], e: 'La avaricia de reconocimiento genera hambre de afecto y la lleva a sobrevalorar lo poco que él brinda. Es un micromachismo encubierto.', t: 'micromachismos' },

  // ── Mitos del amor romántico y celos ──
  { p: '"Si me cela, es porque me quiere". ¿Qué confusión hay detrás de esta idea?', o: ['Confundir el amor con la posesión', 'Confundir la amistad con el amor', 'Confundir la libertad con el abandono', 'Confundir el respeto con la distancia'], e: 'Los celos no son una muestra de amor, sino de posesión.', t: 'mitos-del-amor-romantico' },
  { p: 'Una mujer sigue en una relación violenta convencida de que su amor va a cambiar a su pareja. ¿Qué mito aparece?', o: ['El amor todo lo puede', 'La media naranja', 'Los celos son amor', 'El amor a primera vista'], e: 'Sostiene la esperanza de que el amor va a cambiar a la pareja y hace más difícil salir o pedir ayuda (Herrezuelo Sáez, 2013).', t: 'mitos-del-amor-romantico' },
  { p: 'Una persona controla; la otra se retrae; la primera lo toma como prueba y controla más. ¿Qué describe?', o: ['El círculo de los celos', 'La socialización diferencial', 'La cosificación', 'El balance entre seguridad y libertad'], e: 'Es el círculo de los celos: el retraimiento se lee como prueba de la sospecha y el control aumenta.', t: 'mitos-del-amor-romantico' },
  { p: 'Una pareja "acuerda" que ninguno puede tener amistades propias. Según la guía…', o: ['Es control, aunque se lo llame acuerdo', 'Es un límite sano que eligieron juntos', 'Es una forma de equilibrar la libertad', 'Es una regla propia de cada pareja'], e: 'Un acuerdo nunca puede incluir control: prohibir amistades es violencia, aunque se lo llame "acuerdo".', t: 'mitos-del-amor-romantico' },
  { p: 'Ver a una mujer como un objeto que le pertenece al varón se llama…', o: ['Cosificación', 'Socialización diferencial', 'Androcentrismo', 'Personalización'], e: 'La cosificación impide verla como una persona con voluntad y derechos (Batres, 1989).', t: 'mitos-del-amor-romantico' },
  { p: 'Según Mitchell, ¿qué deseamos todos en una pareja?', o: ['Lo previsible del hogar y también autonomía', 'Seguridad, aunque se pierda autonomía', 'Libertad, aunque se pierda estabilidad', 'Que el otro decida por los dos'], e: 'Mitchell (2002): deseamos lo previsible del hogar y, a la vez, autonomía para explorar lo nuevo.', t: 'mitos-del-amor-romantico' },

  // ── Patriarcado y masculinidades ──
  { p: 'Según Klaudio Duarte, ¿cómo se reproduce el patriarcado?', o: ['Con sexismo, homofobia y heteronormatividad', 'Con la herencia: se nace machista', 'Con alcoholismo, adicción al trabajo y violencia', 'Con la competencia y los logros externos'], e: 'Para Duarte no se nace machista: el patriarcado se reproduce mediante sexismo, homofobia, falocentrismo y heteronormatividad, que pueden desaprenderse. El alcoholismo es de Holloway; la competencia, del código que describe Allen.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según Kali Holloway, ¿cuáles son las manifestaciones más dañinas de la masculinidad tradicional?', o: ['Alcohol, adicción al trabajo y violencia', 'Timidez, tristeza y llanto delante de otros', 'Ser delgados, bellos y siempre serviciales', 'Gusto por la lectura, el arte y el deporte'], e: 'Holloway (2015): aunque no maten, producen una “muerte espiritual” (trauma, disociación y depresión). Ser delgadas, bellas y serviciales es, según ella, lo que se les exige a las mujeres.', t: 'patriarcado-y-masculinidades' },
  { p: '¿Qué es la “muerte espiritual” que menciona Holloway?', o: ['Trauma, disociación y depresión', 'La pérdida de la fe religiosa', 'Un tipo de violencia física', 'El retiro de la vida laboral'], e: 'Es el daño que producen los mandatos masculinos aunque no maten.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según Marvin Allen, ¿qué le pasa a quien viola el código masculino?', o: ['Es humillado', 'Es premiado', 'Es imitado', 'Es ignorado'], e: 'Se anima a competir, soportar el dolor y reprimir la vulnerabilidad; quien no cumple es humillado.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según la guía, ¿cómo suelen procesar el dolor los hombres?', o: ['Lo exteriorizan, hacia sí o hacia otros', 'Lo interiorizan y se responsabilizan', 'No lo sienten: tienen menos emociones', 'Lo hablan y lo elaboran en terapia'], e: 'Las mujeres suelen interiorizarlo y responsabilizarse; los hombres lo exteriorizan, como “víctimas coléricas”. No tienen menos emociones: aprenden a no mostrarlas.', t: 'patriarcado-y-masculinidades' },
  { p: '¿Por qué la depresión masculina casi nunca se diagnostica, según la guía?', o: ['La tapa la exteriorización del dolor', 'Los varones casi nunca se deprimen', 'No existen tratamientos para ellos', 'Interiorizan el dolor y se responsabilizan'], e: 'Según la guía, las mujeres suelen interiorizar el dolor y responsabilizarse; los hombres lo exteriorizan, hacia sí o hacia otros (“víctimas coléricas”). Esa exteriorización (adicción al trabajo, alcohol, violencia) enmascara la depresión.', t: 'patriarcado-y-masculinidades' },

  // ── Violencia en el fútbol ──
  { p: 'Un hincha que jamás pelearía en la calle insulta y tira objetos en la cancha. ¿Qué muestra, según la guía?', o: ['Que en el fútbol la violencia está legitimada', 'Que es una persona violenta por naturaleza', 'Que el fútbol vuelve irracional a la gente', 'Que seguramente es parte de una barra'], e: 'Personas que rechazan la violencia en otros contextos la aceptan en la cancha: allí goza de una aceptación amplia.', t: 'violencia-en-el-futbol' },
  { p: 'Llamar "bestias" o "locos" a quienes cometen hechos violentos…', o: ['Oculta sus causas sociales y culturales', 'Explica con precisión por qué lo hacen', 'Ayuda a prevenir futuros hechos', 'Es la mirada de la antropología'], e: 'La violencia no es un sinsentido: es el resultado de causas sociales y culturales, y tiene significados para quienes la ejercen.', t: 'violencia-en-el-futbol' },
  { p: 'Dentro de la barra, no pelear se vive como…', o: ['Una deshonra, como "falta de hombría"', 'Una muestra de inteligencia y calma', 'Un signo de respeto hacia el rival', 'Una decisión que nadie juzga'], e: 'Los hechos violentos dan honor y prestigio; no pelear se vive como deshonra. Se conecta con un modelo de masculinidad.', t: 'violencia-en-el-futbol' },
  { p: 'Un dirigente recibe a la barra como "embajadora del club". Según la guía, eso…', o: ['Habilita la violencia', 'Ayuda a controlar a la barra', 'Es una medida de prevención', 'No tiene relación con la violencia'], e: 'Es uno de los ejemplos de cómo actores fuera de la barra habilitan la violencia.', t: 'violencia-en-el-futbol' },
  { p: '¿Por qué la identidad del "aguante" es inestable?', o: ['Porque hay que demostrarla una y otra vez', 'Porque depende de los resultados del equipo', 'Porque cambia en cada temporada', 'Porque la otorgan los dirigentes'], e: 'No alcanza con decir que se tiene aguante: hay que demostrarlo una y otra vez.', t: 'violencia-en-el-futbol' },
  { p: 'Si la violencia se ve como parte de la "naturaleza" de algunas personas, ¿qué respuesta queda?', o: ['Solo la represión', 'La prevención con todos los actores', 'El trabajo con los medios', 'Las normas de convivencia en los clubes'], e: 'Si es "naturaleza", solo queda reprimir; si se entiende como algo aprendido, hay lugar para la prevención.', t: 'violencia-en-el-futbol' },

  // ── Diversidad sexual ──
  { p: 'Una persona trans es aquella cuya identidad de género…', o: ['Es distinta del sexo asignado al nacer', 'Coincide con el sexo asignado al nacer', 'No incluye ninguna atracción sexual', 'Depende de su orientación sexual'], e: 'Transgénero: la identidad es diferente al sexo asignado al nacer.', t: 'diversidad-sexual' },
  { p: 'Según la guía, ¿qué relación hay entre la identidad de género y el sexo asignado al nacer?', o: ['Pueden coincidir o no', 'La identidad se deduce del sexo', 'Ambas se definen en la pubertad', 'Coinciden salvo en casos médicos'], e: 'La identidad de género es el sentir interno de cada persona: puede coincidir o no con el sexo asignado al nacer (cisgénero o trans) y no está determinada por el sexo biológico.', t: 'diversidad-sexual' },
  { p: '¿Qué es la asexualidad?', o: ['La falta de atracción sexual hacia otros', 'La atracción por más de un género', 'Una identidad que no es hombre ni mujer', 'La atracción por el mismo sexo'], e: 'Es una orientación: la falta de atracción sexual hacia otras personas.', t: 'diversidad-sexual' },
  { p: 'Según la guía, la discriminación por orientación sexual o identidad de género…', o: ['Vulnera múltiples derechos humanos', 'Afecta sobre todo la vida en pareja', 'Ya no existe desde la Ley 26.618', 'Solo ocurre en el ámbito laboral'], e: 'Vulnera educación, salud integral, empleo, acceso a la justicia y participación pública. Los datos del Observatorio (102 crímenes de odio en el primer semestre de 2025) muestran que sigue existiendo.', t: 'diversidad-sexual' },
  { p: 'Según la ONU, frente a los derechos LGBTI+ el Estado debe…', o: ['Intervenir activamente para protegerlos', 'Garantizarlos solo si hay denuncia', 'Delegar su defensa en las ONG especializadas', 'Reconocerlos sin políticas específicas'], e: 'Según la ONU, el Estado debe intervenir activamente para proteger estos derechos, no limitarse a reconocerlos ni esperar una denuncia.', t: 'diversidad-sexual' },
  { p: 'Según el Observatorio Nacional de Crímenes de Odio LGBT+ (primer semestre de 2025), ¿quiénes concentran las lesiones al derecho a la vida?', o: ['Las mujeres trans', 'Los varones gays', 'Las mujeres lesbianas', 'Las personas bisexuales'], e: 'Las mujeres trans concentran el 86 % de las lesiones al derecho a la vida. En ese semestre hubo 102 crímenes de odio, un 70 % más que en el mismo período anterior.', t: 'diversidad-sexual' },

  // ── Entendimiento de la ira ──
  { p: 'Usar la ira para castigar o vengarse, a la larga…', o: ['Vuelve enemigos a quienes más queremos', 'Hace que los demás nos respeten mucho más', 'Mejora la relación con los demás', 'Resuelve los conflictos pendientes'], e: 'Da un alivio breve, pero convierte en enemigos a las personas que más se quiere y necesita.', t: 'entendimiento-de-la-ira' },
  { p: 'Antes se creía que gritar o pegarle a una almohada era terapéutico. ¿Qué encontraron las investigaciones?', o: ['Que no siempre conviene descargar el enojo', 'Que es la mejor forma de manejar el enojo', 'Que solo funciona en niños y adolescentes', 'Que sirve si se practica todos los días'], e: '“Siempre es deseable expresar el enojo” es uno de los mitos sobre el enojo.', t: 'entendimiento-de-la-ira' },
  { p: 'Una persona empieza a pensar: “me está provocando a propósito”. ¿Qué tipo de señal de intensificación del enojo es?', o: ['Cognitiva', 'Fisiológica', 'Conductual', 'Emocional'], e: 'Las señales de intensificación pueden ser fisiológicas, conductuales, emocionales o cognitivas; un pensamiento que atribuye mala intención es una señal cognitiva.', t: 'entendimiento-de-la-ira' },
  { p: 'La explosión del ciclo de agresión equivale, en la escala del enojo, al…', o: ['10', '1', '5', '7'], e: 'Es la descarga descontrolada en forma de agresión física o verbal.', t: 'entendimiento-de-la-ira' },
  { p: 'Perder seres queridos, sentir culpa y arrepentimiento son parte de la fase de…', o: ['Post-explosión', 'Intensificación', 'Explosión', 'Calma'], e: 'La post-explosión trae las consecuencias negativas: despido, pérdidas, culpa, vergüenza.', t: 'entendimiento-de-la-ira' },
  { p: 'Los pensamientos que desencadenan el enojo nos hacen sentir…', o: ['Víctimas de un daño a propósito', 'Responsables de lo que ocurrió', 'Tranquilos y comprendidos', 'Indiferentes ante lo que pasó'], e: 'Son interpretaciones que culpan y condenan a los demás.', t: 'entendimiento-de-la-ira' },

  // ── El cerebro y las emociones ──
  { p: '¿Qué hace el sistema límbico con lo que nos produce dolor?', o: ['Nos lleva a evitarlo', 'Nos lleva a repetirlo', 'Lo analiza con lógica', 'Lo olvida enseguida'], e: 'Repetimos lo que produce emociones agradables y evitamos lo que produce dolor.', t: 'cerebro-y-emociones' },
  { p: 'Según la visión actual de las neurociencias, ¿qué importa más del cerebro?', o: ['Cómo se conectan sus partes', 'La función aislada de cada parte', 'El tamaño de cada estructura', 'La antigüedad de cada parte'], e: 'Importa cómo trabajan en conjunto; además, la evolución no fue escalonada.', t: 'cerebro-y-emociones' },
  { p: 'Al analizar una emoción, la pregunta “¿qué querías hacer?” sirve para…', o: ['Reconocer el impulso', 'Describir la situación', 'Ver las consecuencias', 'Encontrar al culpable'], e: 'No siempre se actúa: notar que se controló un impulso da esperanza de controlar otros.', t: 'cerebro-y-emociones' },
  { p: '¿Por qué las emociones secundarias causan más problemas que las primarias?', o: ['Encadenan emociones negativas', 'Son más rápidas que las primarias', 'Aparecen sin ningún motivo', 'Nunca se pueden identificar'], e: 'Son “sentimientos de los sentimientos” que se encadenan: enojo, después culpa.', t: 'cerebro-y-emociones' },
  { p: 'Marcela se desborda al encontrar, una vez más, a su marido alcoholizado. Si su emoción primaria es la ira, ¿cuáles son las secundarias, según la guía?', o: ['Desesperanza y vergüenza', 'Tensión muscular y náuseas', 'Entusiasmo y alegría', 'Sorpresa y curiosidad'], e: 'La guía identifica la ira como primaria y la desesperanza y la vergüenza como secundarias. La tensión muscular y las náuseas son sensaciones corporales, no emociones.', t: 'cerebro-y-emociones' },

  // ── Abordaje emocional (IFS) ──
  { p: 'En el modelo IFS, consumir o comprar en exceso después de un rechazo es una forma de…', o: ['Distraer del dolor', 'Criticar para proteger', 'Cuidar a otros', 'Volverse encantador'], e: 'Es un mecanismo de los protectores: distraer del dolor (trabajar mucho, consumir, comprar en exceso) cuando nos rechazan, critican o ignoran. “Criticar para proteger”, en cambio, empuja a ser más productivo para evitar la crítica ajena.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿qué intenta una parte cuando se activa?', o: ['Sacar al Yo del control y tomar su lugar', 'Unirse al Yo para sanar juntas', 'Desaparecer para siempre del sistema interno', 'Avisarle al exiliado que hay peligro'], e: 'Cuando una parte se activa, intenta asumir el rol del Yo.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿cómo conviene tratar a una parte que nos afecta?', o: ['Escucharla desde el Yo, con curiosidad', 'Fundirse con ella para entenderla mejor', 'Negarla hasta que deje de activarse', 'Censurarla para que no tome el control'], e: 'No hay que fundirse con ella, ni negarla ni censurarla: está diciendo algo sobre nuestra historia. Se la escucha desde el Yo para comprenderla, aceptarla y darle tranquilidad.', t: 'abordaje-emocional-ifs' },
  { p: '¿Qué es “reparentalizar” al exiliado?', o: ['Darle desde el Yo lo que necesitó de niño', 'Pedirles perdón a los propios padres', 'Olvidar todo lo que pasó en la infancia', 'Buscar una nueva familia que nos cuide'], e: 'El Yo le da una experiencia positiva que reemplaza la de sufrimiento, en la imaginación.', t: 'abordaje-emocional-ifs' },
  { p: 'Según el modelo IFS, ¿qué determina cómo nos sentimos?', o: ['Los residuos emocionales de lo vivido', 'Las experiencias en sí mismas, tal como ocurrieron', 'Solo lo que pasa en el presente', 'La opinión que tienen los demás'], e: 'No son las experiencias en sí, sino los residuos emocionales que dejaron.', t: 'abordaje-emocional-ifs' },
  { p: '¿Cómo se siente el cuerpo cuando está presente el Yo?', o: ['En paz, abierto y con energía', 'Tenso y en estado de alerta', 'Cansado, pesado y sin ganas', 'Acelerado y con ansiedad'], e: 'Las partes extremas, en cambio, se notan en tensión, dolores o malestar.', t: 'abordaje-emocional-ifs' },

  // ── Pensamientos automáticos ──
  { p: '¿Por qué se dice que los pensamientos automáticos son “taquigráficos”?', o: ['Son pocas palabras o una imagen breve', 'Se escriben muy rápido en un diario', 'Aparecen solo durante la noche', 'Son frases largas y muy precisas'], e: 'Una frase corta encabeza todo un grupo de recuerdos, temores o autorreproches.', t: 'pensamientos-automaticos' },
  { p: '¿Por qué los pensamientos automáticos casi nunca se cuestionan?', o: ['Porque casi no se notan', 'Porque siempre son ciertos', 'Porque los dice otra persona', 'Porque son muy largos'], e: 'Casi no se notan, y por eso no se analizan lógicamente.', t: 'pensamientos-automaticos' },
  { p: 'Según la guía, ¿qué característica de los pensamientos automáticos es la mayor fuente de ansiedad?', o: ['Que tienden a dramatizar', 'Que son taquigráficos', 'Que son idiosincráticos', 'Que son aprendidos'], e: 'Tienden a dramatizar: predicen catástrofes y suponen lo peor. Por eso son la mayor fuente de ansiedad.', t: 'pensamientos-automaticos' },
  { p: 'Para reconocer un pensamiento automático, conviene…', o: ['Reconstruir la escena en cámara lenta', 'Olvidar rápido lo que pasó', 'Pedirle a otra persona que lo adivine por uno', 'Esperar a que se repita solo'], e: 'Repasarla en la imaginación hasta que emerja la emoción y observar frase a frase.', t: 'pensamientos-automaticos' },
  { p: 'La frase taquigráfica “loco”, desarrollada, puede significar…', o: ['“Siento que pierdo el control”', '“Él me está dominando”', '“Ella está aburrida”', '“Voy a estar acá toda la noche”'], e: 'Desarrollarla lleva a la idea completa: “siento que pierdo el control y eso podría significar…”.', t: 'pensamientos-automaticos' },
  { p: 'Que cada persona reaccione distinto ante la misma situación muestra que los pensamientos automáticos son…', o: ['Idiosincráticos', 'Hereditarios', 'Universales y fijos', 'Racionales'], e: 'Son relativamente idiosincráticos: propios de cada persona.', t: 'pensamientos-automaticos' },

  // ── Distorsiones cognitivas ──
  { p: '"Debería haber llegado hace una hora; seguro está con otra persona". ¿Qué distorsión es?', o: ['Conclusión arbitraria', 'Generalización excesiva', 'Pensamiento dicotómico', 'Filtraje'], e: 'Saca una conclusión sin pruebas suficientes.', t: 'distorsiones-cognitivas' },
  { p: '"No la golpeé, solo la agarré fuerte". ¿Qué distorsión aparece?', o: ['Minimización', 'Maximización', 'Personalización', 'Abstracción selectiva'], e: 'Achica la importancia del hecho y niega el impacto real y la responsabilidad de una conducta violenta.', t: 'distorsiones-cognitivas' },
  { p: 'El jefe frunció el ceño una vez en una reunión que salió bien, y alguien concluye "salió todo mal". ¿Qué distorsión es?', o: ['Abstracción selectiva', 'Falacia de recompensa divina', 'Minimización', 'Personalización'], e: 'Se fija en un detalle fuera de contexto y juzga toda la situación por él.', t: 'distorsiones-cognitivas' },
  { p: 'Alguien se sacrificó años por su familia y está amargado porque "nadie se lo reconoció". ¿Qué distorsión puede haber?', o: ['Falacia de recompensa divina', 'Personalización', 'Minimización', 'Pensamiento dicotómico'], e: 'Esperar que el sacrificio sea recompensado algún día, como si alguien llevara la cuenta; si no llega, aparecen la amargura y el resentimiento.', t: 'distorsiones-cognitivas' },
  { p: '¿Qué distingue al filtraje dentro de la abstracción selectiva?', o: ['Que solo retiene lo negativo', 'Que supone lo que piensan los demás', 'Que generaliza a partir de un hecho', 'Que ve todo en extremos opuestos'], e: 'El filtraje es una forma de abstracción selectiva que se queda solo con lo negativo y descarta lo positivo.', t: 'distorsiones-cognitivas' },
  { p: '¿Qué se anota en el registro para trabajar las distorsiones?', o: ['Contexto, situación, emoción, pensamiento y distorsión', 'Hora, lugar, persona, conducta y castigo recibido', 'Acontecimiento, creencia, consecuencia y debate', 'Fecha, síntoma, diagnóstico, tratamiento y dosis'], e: 'Son las cinco columnas del registro. El ABC de Ellis es otra herramienta, del tema Pensar correctamente.', t: 'distorsiones-cognitivas' },

  // ── Pensar correctamente ──
  { p: 'En el ABC de Ellis, ¿dónde se encuentra la solución al problema?', o: ['En la D', 'En la A', 'En la C', 'En la B'], e: 'A activa, B (la creencia) causa C, y en D está la solución.', t: 'pensar-correctamente' },
  { p: 'En los conflictos cotidianos, frente al mito “hay gente malvada que debe ser castigada”, la guía señala que…', o: ['Una mala conducta no hace mala a la persona', 'Quien nos molesta suele hacerlo a propósito', 'Hay que devolver cada daño recibido', 'El castigo es la mejor forma de corregir'], e: 'Pocas cosas son absolutamente buenas o malas. Esto vale para los roces cotidianos: no contradice que la violencia de género deba sancionarse (Ley 26.485, art. 7).', t: 'pensar-correctamente' },
  { p: 'Según Ellis, preocuparse sin parar por algo peligroso…', o: ['No impide que ocurra', 'Evita que llegue a suceder', 'Lo vuelve menos grave', 'Es una forma de controlarlo'], e: 'Es uno de los mitos irracionales: preocuparse no impide que ocurra, y la mayoría de lo temido no sucede o es menos grave.', t: 'pensar-correctamente' },
  { p: 'Evitar las dificultades en lugar de enfrentarlas…', o: ['Crea más problemas', 'Las resuelve solas', 'Da más confianza', 'Sube la autoestima'], e: 'Enfrentarlas es lo que aumenta la confianza y la autoestima.', t: 'pensar-correctamente' },
  { p: 'Frente a la idea de que cada problema tiene una solución perfecta, la guía sugiere…', o: ['Elegir una buena y, si falla, probar otra', 'Esperar con paciencia hasta encontrar la perfecta', 'Dejar que otro decida por nosotros', 'No hacer nada hasta estar seguros'], e: 'Hay muchas soluciones posibles y rara vez una perfecta.', t: 'pensar-correctamente' },
  { p: 'En los vínculos cotidianos, ante el mito de que hay que cambiar a los demás, ¿qué propone la guía?', o: ['Vivir y dejar vivir', 'Insistir hasta que cambien', 'Alejarse de todos', 'Ceder siempre'], e: 'Intentar cambiar la conducta ajena suele empeorar las cosas. Ojo: vale para diferencias cotidianas. La violencia no es un asunto privado y requiere la intervención del Estado y la sociedad civil (modelo ecológico; Ley 26.485).', t: 'pensar-correctamente' },

  // ── Teoría del apego ──
  { p: 'Un bebé llora y quien lo cuida a veces lo consuela con cariño y otras lo ignora. ¿Qué estilo se asocia?', o: ['Ambivalente', 'Seguro', 'Evitativo', 'Desorganizado'], e: 'En el apego ambivalente, quien cuida responde de forma inconstante; predominan la inseguridad y la demanda permanente de afecto.', t: 'teoria-del-apego' },
  { p: '¿Qué mostraron los experimentos de Harlow con monos?', o: ['La necesidad de contacto, más allá del alimento', 'Que las crías siguen a lo primero que ven moverse', 'Que los monos aprenden a usar herramientas', 'Que el apego depende solo de la comida'], e: 'Harlow mostró la necesidad de contacto y consuelo. Seguir a la primera figura en movimiento es la impronta que estudió Lorenz.', t: 'teoria-del-apego' },
  { p: 'Konrad Lorenz mostró que las crías de ave…', o: ['Se vinculan con la primera figura en movimiento', 'Necesitan más el contacto que el alimento', 'Imitan el canto de sus padres desde el nido', 'Reconocen a su madre por el olor de las plumas'], e: 'Es la impronta: un vínculo fuerte con la primera figura en movimiento que ven.', t: 'teoria-del-apego' },
  { p: '¿Qué estilo es frecuente cuando la figura que debería dar seguridad también da miedo?', o: ['Desorganizado', 'Seguro', 'Ambivalente', 'Evitativo'], e: 'El estilo desorganizado, que sumaron Main y Solomon (1990). Es frecuente en situaciones de maltrato, aunque no solo en ellas.', t: 'teoria-del-apego' },
  { p: '¿Qué puede dar seguridad a un adulto con una historia de apego inseguro?', o: ['Vínculos posteriores, como amistades o terapia', 'Nada: el apego no cambia después de la infancia', 'Evitar todo vínculo cercano', 'Volver a vivir con su familia de origen'], e: 'Los estilos son tendencias: una pareja, amistades o un espacio terapéutico también pueden dar seguridad.', t: 'teoria-del-apego' },
  { p: 'En la teoría del apego, "accesibilidad" se refiere a…', o: ['Cuánto se espera que quien cuida esté disponible', 'La facilidad para llegar a un servicio de salud', 'La capacidad del niño de explorar el mundo', 'La cantidad de contacto físico con el bebé'], e: 'Es la expectativa sobre la disponibilidad y la respuesta de quien cuida; esa expectativa va formando el carácter.', t: 'teoria-del-apego' },

  // ── Personalidad ──
  { p: '¿Qué afecto suele llevar a consulta a una persona con estilo paranoide?', o: ['La ansiedad constante', 'El remordimiento y el autocastigo', 'La euforia del vínculo asegurado', 'La indiferencia afectiva'], e: 'Vive con cólera por el presunto abuso y ansiedad constante por las amenazas que percibe, que suele ser el motivo de consulta. El remordimiento es del estilo obsesivo; la euforia, del dependiente.', t: 'personalidad' },
  { p: '¿Cómo ve a los demás la personalidad obsesivo-compulsiva?', o: ['Irresponsables o incompetentes', 'Superiores, admirables y dignos de imitar', 'Críticos y despectivos', 'Fuertes y protectores'], e: 'Se cree responsable de que todo se haga bien y ve a los otros como despreocupados.', t: 'personalidad' },
  { p: '¿Qué amenaza más a la personalidad narcisista?', o: ['Lo que dañe su autoestima', 'El acercamiento excesivo', 'El rechazo o el abandono', 'Los errores y el desorden'], e: 'Su clave es la autoexaltación. Las otras amenazas son de otros estilos.', t: 'personalidad' },
  { p: 'La personalidad por evitación querría estar cerca de los demás, pero teme…', o: ['Ser herida, rechazada o fracasar', 'Perder su libertad para decidir sola', 'Que la admiren demasiado', 'Que la necesiten demasiado'], e: 'Su estrategia es evitar situaciones donde pueda ser evaluada.', t: 'personalidad' },
  { p: '¿Qué siente la personalidad por dependencia cuando su vínculo está asegurado?', o: ['Euforia', 'Cólera', 'Indiferencia', 'Culpa'], e: 'Ansiedad ante una posible ruptura, depresión si pierde a la figura, euforia si está asegurada.', t: 'personalidad' },
  { p: '¿Cuál es el conflicto central del estilo pasivo-agresivo?', o: ['Querer aprobación y a la vez autonomía', 'Querer admiración sin dar nada a cambio', 'Querer estar solo y acompañado', 'Querer orden en medio del caos'], e: 'Desea las ventajas de la autoridad y a la vez conservar su autonomía.', t: 'personalidad' },

  // ── El duelo ──
  { p: 'Pocos días después de la muerte de su pareja, una mujer sigue su rutina casi en automático, con estallidos de angustia. ¿En qué fase está?', o: ['Embotamiento', 'Anhelo y búsqueda', 'Desorganización y desesperanza', 'Reorganización'], e: 'En el embotamiento la persona puede seguir casi en automático, tensa, con estallidos de angustia o de enojo.', t: 'duelo' },
  { p: 'Meses después de la pérdida, alguien siente la presencia de su padre y cree oír su voz al entrar en casa. ¿Qué fase se asocia?', o: ['Anhelo y búsqueda', 'Embotamiento', 'Reorganización', 'Ausencia de duelo'], e: 'En el anhelo y la búsqueda aparecen sentir la presencia de la persona o interpretar señales de que volvió.', t: 'duelo' },
  { p: '¿Qué tienen en común el duelo crónico y la ausencia de duelo?', o: ['La pérdida no se acepta como definitiva', 'Las emociones son siempre muy intensas', 'La persona no siente nada por la pérdida', 'Ambos se resuelven solos en semanas'], e: 'En ambos casos la pérdida no se acepta como definitiva y la persona queda detenida en la segunda o la tercera fase.', t: 'duelo' },
  { p: '¿Cuál de estas señales, si no cede con el paso del tiempo, puede indicar un duelo complicado?', o: ['Una tristeza profunda que no cede', 'Llorar al recordar a la persona', 'Sentir enojo en las primeras semanas', 'Sentir a veces su presencia'], e: 'La tristeza, el enojo y hasta sentir la presencia de quien murió son parte de un duelo esperable. Lo que preocupa es que la tristeza no ceda con el tiempo. Si aparecen ideas de quitarse la vida, hay que pedir ayuda enseguida (línea 135).', t: 'duelo' },
  { p: '¿Qué ayuda a prevenir que el duelo se complique?', o: ['Contar lo que pasó a toda la familia', 'Ocultarles la muerte a los más chicos', 'Evitar hablar de la persona fallecida', 'Buscar un culpable de lo que pasó'], e: 'Contar lo que pasó a toda la familia (también a niñas y niños, con palabras acordes a su edad) y evitar culpabilizar o culpabilizarse.', t: 'duelo' },
  { p: '¿Qué función cumple un velatorio para quienes quedan?', o: ['Muestra que la pérdida es real', 'Prolonga el duelo para hacerlo más profundo', 'Evita que se exprese el dolor en público', 'Reemplaza la necesidad de hablar del tema'], e: 'Según Firth, los rituales muestran que la pérdida es real, permiten expresar el dolor en público y dan un nuevo lugar en la comunidad.', t: 'duelo' },

  // ── Habilidades interpersonales ──
  { p: '¿Qué pasa a corto plazo con la conducta pasiva?', o: ['Parece proteger la relación', 'Destruye la relación enseguida', 'Resuelve el conflicto de fondo', 'Hace que el otro cambie'], e: 'A la larga genera frustración y resentimiento y vuelve insostenible la relación.', t: 'habilidades-interpersonales' },
  { p: 'El equilibrio “yo quiero – los otros quieren” implica…', o: ['Decir lo propio y averiguar lo ajeno', 'Ceder para no dañar la relación', 'Cumplir con lo que uno debería hacer', 'Lograr que el otro acepte lo nuestro'], e: 'Saber y decir lo que se desea, averiguar lo que desea el otro, negociar y dar lo que se pueda. Ceder es la conducta pasiva; el “debería” es el otro equilibrio.', t: 'habilidades-interpersonales' },
  { p: 'Cargarse de “debería” en una relación…', o: ['Hace que uno quiera escaparse de ella', 'Genera resentimiento en la otra persona', 'Demuestra compromiso y responsabilidad', 'Le da estabilidad y previsibilidad'], e: 'Es el equilibrio “quiero – debería”: cargarse de “debería” convierte la relación en una carga de la que se quiere escapar. El resentimiento del otro aparece al revés, cuando uno se centra solo en lo que quiere.', t: 'habilidades-interpersonales' },
  { p: 'Según la guía, jugar con objetos mientras se habla puede indicar…', o: ['Nerviosismo', 'Seguridad', 'Interés', 'Alegría'], e: 'Es un ejemplo de lenguaje corporal; un apretón de manos, en cambio, transmite seguridad. Es una señal posible, no una regla: ante la duda, conviene preguntar.', t: 'habilidades-interpersonales' },
  { p: 'En el esquema para resolver problemas, ¿qué se pregunta al evaluar las opciones?', o: ['¿Qué gano y qué pierdo?', '¿Quién tiene la culpa?', '¿Qué dirán los demás?', '¿Cuánto tiempo tengo?'], e: 'Se analizan ventajas, desventajas y consecuencias de cada opción.', t: 'habilidades-interpersonales' },
  { p: 'Si los resultados de la solución elegida son negativos, ¿qué conviene hacer?', o: ['Revisar el error o buscar otra solución', 'Abandonar el problema para siempre', 'Culpar a las personas que participaron en él', 'Repetir lo mismo con más fuerza'], e: 'Es el último paso del esquema: analizar los resultados.', t: 'habilidades-interpersonales' },

  // ── Límites y negociación ──
  { p: 'Decir “no puedo porque soy torpe” al poner un límite…', o: ['Deja espacio para que nos convenzan', 'Es la forma más firme y clara de negarse', 'Muestra seguridad y confianza', 'Evita cualquier discusión'], e: 'Mejor “no lo haré” o “no quiero hacerlo”, que dejan menos lugar para discutir.', t: 'limites-y-negociacion' },
  { p: '“Puedo revisar tu proyecto, pero no voy a participar en la producción” es un ejemplo de…', o: ['Ser específico', 'Pedir disculpas', 'Retrasar la respuesta', 'Descalificarse'], e: 'Aclarar qué se está dispuesto a hacer y qué no.', t: 'limites-y-negociacion' },
  { p: '“Quiero que laves los platos antes de mirar televisión” expresa un deseo en términos…', o: ['Conductuales', 'Vagos', 'Emocionales', 'Agresivos'], e: 'Es el segundo paso de la negociación: decir claramente qué se espera que el otro haga.', t: 'limites-y-negociacion' },
  { p: 'Si al otro no le gusta nuestra propuesta, ¿cuál es el paso siguiente?', o: ['Pedir una contrapropuesta', 'Insistir con la misma', 'Abandonar la negociación', 'Ceder en todo'], e: 'Animar al otro a plantear una alternativa que satisfaga a ambas partes.', t: 'limites-y-negociacion' },
  { p: '¿Qué se usa para escuchar el punto de vista del otro en una negociación?', o: ['Preguntas abiertas y paráfrasis', 'Interrupciones y correcciones', 'Silencios y gestos de rechazo', 'Argumentos para refutarlo'], e: 'Escucha activa: preguntas abiertas, aclaraciones y paráfrasis.', t: 'limites-y-negociacion' },
  { p: 'Antes de decir que no, la primera pauta es…', o: ['Reconocer las necesidades del otro', 'Pedir disculpas por tener que negarse', 'Buscar una excusa creíble', 'Cambiar rápido de tema'], e: 'Pedir más información y, si hace falta, reformular el pedido para comprobar que se entendió.', t: 'limites-y-negociacion' },

  // ── Nuevas familias ──
  { p: 'Una madre que cría sola a su hija desde el nacimiento forma una familia…', o: ['Monoparental', 'Extensa', 'Ensamblada', 'Nuclear'], e: 'Es una familia monoparental; cuando la madre cría sola desde el inicio, a veces se la llama monomarental.', t: 'nuevas-familias' },
  { p: 'Después de separarse, un padre le dice a su hijo: "No le hagas caso a tu madre". ¿Qué está haciendo?', o: ['Desautorizar al otro progenitor', 'Ejercer la responsabilidad parental', 'Proteger a su hijo de un riesgo', 'Enseñarle normas de convivencia'], e: 'Desautorizar al otro progenitor confunde a los hijos sobre a quién respetar.', t: 'nuevas-familias' },
  { p: '"No le cuentes esto a papá". Según la guía, pedir secretos así…', o: ['Pone a los hijos en un lugar que no les toca', 'Fortalece la confianza entre madre e hijo', 'Evita conflictos innecesarios en la familia', 'Es una parte normal de toda separación'], e: 'Pedirles que guarden secretos los pone en un lugar que no les corresponde.', t: 'nuevas-familias' },
  { p: 'Una madre pide medidas para proteger a sus hijos de un padre que ejerce violencia. Según la guía…', o: ['Es protegerlos, no "poner en contra"', 'Es desautorizar al otro progenitor', 'Es usarlos como moneda de cambio', 'Es obligarlos a elegir un bando'], e: 'Las pautas sobre la separación son para separaciones sin violencia. Cuando hay violencia, proteger a los hijos no es "desautorizar" ni "poner en contra", y las medidas de restricción de acercamiento pueden extenderse a ellos.', t: 'nuevas-familias' },
  { p: 'Según Grosman y Mesterman, la familia a veces puede ser…', o: ['Una escuela de violencia', 'Un espacio sin conflictos', 'Un refugio siempre seguro', 'Una institución sin cambios'], e: 'A veces es una escuela de violencia, donde niñas y niños aprenden que agredir sirve para controlar a los demás.', t: 'nuevas-familias' },
  { p: 'Cuando la tensión por trabajo o dinero se descarga como violencia sobre mujeres o hijos, ¿qué hay detrás, según la guía?', o: ['Una relación desigual de poder', 'Un estrés imposible de controlar', 'Una descarga normal de la tensión', 'Un problema de adicciones'], e: 'Pueden tensar la vida familiar, pero no explican ni justifican la violencia: cuando se descarga sobre mujeres o hijos, hay una relación desigual de poder.', t: 'nuevas-familias' },

  // ── Relajación avanzada ──
  { p: 'En la respiración con escenas de estrés, ¿qué intensidad de ira deben provocar las escenas?', o: ['Entre 5 y 7', 'Entre 3 y 5', 'Entre 7 y 9', 'Entre 1 y 3'], e: 'Se eligen dos escenas de ira moderada, entre 5 y 7 en una escala de 1 a 10.', t: 'relajacion-avanzada' },
  { p: 'En la respiración con escenas de estrés, ¿en cuántas partes se divide cada escena?', o: ['Tres', 'Dos', 'Cinco', 'Diez'], e: 'Tres partes, con un recordatorio de respirar al final de cada una. Dos es la cantidad de escenas, no de partes.', t: 'relajacion-avanzada' },
  { p: '¿Qué cambia en la relajación sin tensión respecto de la progresiva?', o: ['Se quita el paso de tensar', 'Se tensa el doble de tiempo', 'Se hace sin respirar hondo', 'Se hace mientras se camina'], e: 'Hasta ahí se relajaba aumentando la tensión; ahora se elimina ese paso.', t: 'relajacion-avanzada' },
  { p: 'En momentos de estrés, la palabra clave reemplaza a…', o: ['La respiración profunda', 'La tensión de cada músculo', 'La visualización de las escenas', 'La medición del nivel de estrés'], e: 'Se vuelve a las escenas de estrés y se reemplaza la respiración profunda por la palabra clave; las escenas se siguen visualizando.', t: 'relajacion-avanzada' },
  { p: 'Ante una situación estresante real, primero se repasa la escena sin relajarse para…', o: ['Ver dónde se acumula la tensión', 'Ensayar una respuesta para la próxima vez', 'Olvidar lo que pasó', 'Medir cuánto dura'], e: 'Después se concentra la relajación en esos grupos musculares.', t: 'relajacion-avanzada' },
];
